import java.util.Optional;
import java.util.stream.Collectors;

@Transactional
@Service
@Slf4j
@RequiredArgsConstructor
public class RoleServiceImpl implements IRoleService {
  private final RoleRepository roleRepository;

  private final RoleResourceRelRepository roleResourceRelRepository;

  private final AdminPermissionLoader adminPermissionLoader;

  /**
   * createImpl
   */
  @Override
  public Long createRole(RoleCreator creator) {
    Optional<Role> role = EntityOperations.doCreate(roleRepository)
    .create(() -> RoleMapper.INSTANCE.dtoToEntity(creator))
    .update(e -> e.init())
    .execute();
    return role.isPresent() ? role.get().getId() : 0;
  }

  /**
   * update
   */
  @Override
  public void updateRole(RoleUpdater updater) {
    EntityOperations.doUpdate(roleRepository)
    .loadById(updater.getId())
    .update(e -> updater.updateRole(e))
    .execute();
  }

  /**
   * valid
   */
  @Override
  public void validRole(Long id) {
    EntityOperations.doUpdate(roleRepository)
    .loadById(id)
    .update(e -> e.valid())
    .execute();
  }

  /**
   * invalid
   */
  @Override
  public void invalidRole(Long id) {
    EntityOperations.doUpdate(roleRepository)
    .loadById(id)
    .update(e -> e.invalid())
    .execute();
  }

  /**
   * findById
   */
  @Override
  public RoleVO findById(Long id) {
    Optional<Role> role =  roleRepository.findById(id);
    return new RoleVO(role.orElseThrow(() -> new BusinessException(CodeEnum.NotFindError)));
  }

  /**
   * findByPage
   */
  @Override
  public Page<RoleVO> findByPage(PageRequestWrapper<RoleQuery> query) {
    BooleanBuilder booleanBuilder = pageCondition(query);
    Page<Role> page = roleRepository.findAll(booleanBuilder,
            PageRequest.of(query.getPage() - 1, query.getPageSize(), Sort.by(
                Sort.Direction.DESC, "createdAt")));
    return new PageImpl<>(page.getContent().stream().map(entity -> new RoleVO(entity))
            .collect(Collectors.toList()), page.getPageable(), page.getTotalElements());
  }

  private BooleanBuilder pageCondition(PageRequestWrapper<RoleQuery> query) {
    BooleanBuilder booleanBuilder = new BooleanBuilder();
    QRole role = QRole.role1;
    if (StringUtils.isNotBlank(query.getBean().getName())) {
      booleanBuilder.and(role.name.like("%" + query.getBean().getName() + "%"));
    }
    if (Objects.nonNull(query.getBean().getPlatformId())) {
      booleanBuilder.and(role.platformId.eq(query.getBean().getPlatformId()));
    }
    return booleanBuilder;
  }

  @Override
  public List<Long> getRoleAllResources(Long roleId) {
    List<RoleResourceRel> list = roleResourceRelRepository.findAllByRoleId(roleId);
    return list.stream().map(RoleResourceRel::getResourceId).collect(Collectors.toList());
  }

  @Override
  public void grantRoleResources(Long roleId, List<Long> resourceIds) {
    Assert.notNull(roleId, AuthErrorCode.ROLE_ID_NULL.getName());
    // 先删除原有的id
    roleResourceRelRepository.deleteByRoleId(roleId);
    if (CollectionUtils.isNotEmpty(resourceIds)) {
      List<RoleResourceRel> collect = resourceIds.stream()
          .map(rId -> {
            RoleResourceRel rel = new RoleResourceRel();
            rel.setRoleId(roleId);
            rel.setResourceId(rId);
            return rel;
          }).collect(Collectors.toList());
      // 将新授权的id保存
      roleResourceRelRepository.saveAll(collect);
    }
    adminPermissionLoader.evictByRole(roleId);
  }

  @Override
  public List<RoleVO> findAllValidRoles() {
    List<Role> list = roleRepository.findAllByValidStatus(ValidStatus.VALID);
    return list.stream().map(RoleMapper.INSTANCE::entityToVo).collect(Collectors.toList());
  }
}
